const RELEASE = {"version":"1.1.0","build":"f723457c94a8"}; // Generated by scripts/release.mjs
const CACHE = `pawbreath-shell-${RELEASE.version}-${RELEASE.build}`;
// The scope root is the app shell document. Do not also list index.html: static hosts such as
// Cloudflare Workers Assets redirect it to the root, and installation rejects redirected responses.
const ASSETS = ['./', './app.css', './app.js', './data.mjs', './updates.mjs', './version.mjs',
  './manifest.webmanifest', './icon-192.png', './icon-512.png'];
const urls = ASSETS.map(path => new URL(path, self.registration.scope).href);

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    for (const url of urls) {
      const response = await fetch(url, { cache: 'reload', credentials: 'same-origin' });
      if (!response.ok || response.redirected) throw new Error('App asset unavailable.');
      // An authentication page must never replace the app shell.
      if (url.endsWith('/')) {
        const body = await response.clone().text();
        if (!body.includes('id="breath-button"')) throw new Error('App shell unavailable.');
      }
      await cache.put(url, response);
    }
  })());
  // Let the next launch activate an update after existing clients close.
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const name of await caches.keys()) {
      if (name.startsWith('pawbreath-shell-') && name !== CACHE) await caches.delete(name);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('fetch', event => {
  if (event.request.method !== 'GET') return;
  const url = new URL(event.request.url);
  url.search = ''; url.hash = '';
  if (!urls.includes(url.href)) return;
  event.respondWith((async () => {
    const cached = await (await caches.open(CACHE)).match(url.href);
    return cached ?? fetch(event.request);
  })());
});
